// Webhook integrity check (opt-in via WEBHOOK_INTEGRITY_CHECK_ENABLED=1).
// Telegram Trigger handles HMAC via its secretToken option (set on the
// trigger node itself). This Code node is the second defense layer:
// reject malformed payloads that lack the fields downstream nodes expect.
//
// To enable: set the n8n env var WEBHOOK_INTEGRITY_CHECK_ENABLED to '1'.
// To disable: leave the env var unset (default). The node passes through.

const enabled = $env.WEBHOOK_INTEGRITY_CHECK_ENABLED === '1';
if (!enabled) {
  return [{ json: $input.first().json }];
}

const item = $input.first().json;
const message = item?.message ?? item;

if (!message || typeof message !== 'object') {
  throw new Error('Webhook integrity check failed: no message object');
}
if (typeof message.from?.id !== 'number' && typeof message.from?.id !== 'string') {
  throw new Error('Webhook integrity check failed: missing message.from.id');
}
if (typeof message.chat?.id !== 'number' && typeof message.chat?.id !== 'string') {
  throw new Error('Webhook integrity check failed: missing message.chat.id');
}
if (typeof message.text !== 'string' && typeof message.caption !== 'string') {
  throw new Error('Webhook integrity check failed: no text or caption');
}

return [{ json: item }];

// Rate limit (opt-in via RATE_LIMIT_ENABLED=1).
// Per-chat-id 60 requests in a 5-minute window. Tracked in workflow
// static data (per-instance). For clustered n8n deployments or higher
// throughput, use Nginx limit_req_zone or Cloudflare WAF instead.
//
// To enable: set the n8n env var RATE_LIMIT_ENABLED to '1'.
// To disable: leave the env var unset (default). The node passes through.
//
// Concurrency note: $getWorkflowStaticData is not atomic. Under heavy
// burst load the count can over-shoot the limit by a few percent. For
// hard limits use a reverse proxy or Redis INCR + EXPIRE.

const enabled = $env.RATE_LIMIT_ENABLED === '1';
if (!enabled) {
  return [{ json: $input.first().json }];
}

const item = $input.first().json;
const message = item?.message ?? item;
const chatId = message?.chat?.id ?? message?.from?.id ?? 'unknown';
const bucketKey = `chat:${chatId}`;

const data = $getWorkflowStaticData('global');
const buckets = data.rateBuckets ?? {};
const now = Date.now();
const WINDOW_MS = 5 * 60 * 1000;
const LIMIT = 60;
const MAX_BUCKETS = 5000;

const bucket = buckets[bucketKey] ?? { count: 0, windowStart: now };
if (now - bucket.windowStart > WINDOW_MS) {
  bucket.count = 0;
  bucket.windowStart = now;
}
bucket.count++;
buckets[bucketKey] = bucket;

// Bound the map: evict expired entries when full
if (Object.keys(buckets).length > MAX_BUCKETS) {
  const cutoff = now - WINDOW_MS;
  for (const k of Object.keys(buckets)) {
    if (buckets[k].windowStart < cutoff) delete buckets[k];
  }
}
data.rateBuckets = buckets;

if (bucket.count > LIMIT) {
  throw new Error(`Rate limit exceeded for ${bucketKey}: ${bucket.count} requests in 5 min window`);
}

return [{ json: item }];

// Idempotency check (opt-in via IDEMPOTENCY_ENABLED=1).
// Telegram retries on 5xx. Without dedup, the workflow fires twice and
// writes Memory twice. This node holds a 5-minute in-memory window of
// seen update_ids and short-circuits duplicates.
//
// To enable: set the n8n env var IDEMPOTENCY_ENABLED to '1'.
// To disable: leave the env var unset (default). The node passes through.
//
// Concurrency note: $getWorkflowStaticData is not atomic and not cluster-
// aware. Two simultaneous fires of the same update_id may both pass.
// For production scale, swap the staticData block for Redis SET NX EX 300.

const enabled = $env.IDEMPOTENCY_ENABLED === '1';
if (!enabled) {
  return [{ json: $input.first().json }];
}

const item = $input.first().json;
const message = item?.message ?? item;
const updateId = item?.update_id ?? message?.update_id;
const messageId = message?.message_id;
const idempotencyKey = updateId ? `tg-update:${updateId}` : (messageId ? `tg-msg:${messageId}` : null);

if (!idempotencyKey) {
  // No dedup key available, pass through
  return [{ json: item }];
}

const data = $getWorkflowStaticData('global');
const seen = data.seenKeys ?? {};
const now = Date.now();
const WINDOW_MS = 5 * 60 * 1000;

// Purge expired entries
for (const k of Object.keys(seen)) {
  if (now - seen[k] > WINDOW_MS) delete seen[k];
}

if (seen[idempotencyKey]) {
  // Duplicate, short-circuit by returning empty array
  return [];
}
seen[idempotencyKey] = now;
data.seenKeys = seen;

return [{ json: item }];

// Extract a stable meeting key from the Fathom or Otter or Granola webhook payload.
// Strategy: combine sorted-participant-emails into a hash (the "participant set"),
// plus persist the meeting_id from the source for idempotency. Fathom and Otter both
// expose a unique meeting_id and a participants array.
//
// Why participant-set: cross-meeting continuity is ONLY meaningful for the SAME
// people. A 1-on-1 with Alex and a 1-on-1 with Sam should not share context.

const body = $input.first().json;

// Source-detection (Fathom vs Otter vs Granola vs Fireflies)
let source = 'unknown';
let meetingId, title, transcript, summary, participants, startedAt;

if (body?.fathom_id || body?.fathom_meeting_id) {
  source = 'fathom';
  meetingId = body.fathom_id ?? body.fathom_meeting_id;
  title = body?.title ?? 'Fathom Meeting';
  transcript = body?.transcript_text ?? body?.transcript ?? '';
  summary = body?.summary?.text ?? body?.summary ?? '';
  participants = (body?.invitees ?? body?.participants ?? []).map(p => p.email ?? p);
  startedAt = body?.scheduled_start_time ?? body?.started_at;
} else if (body?.otter_meeting_id || body?.speech_id) {
  source = 'otter';
  meetingId = body.otter_meeting_id ?? body.speech_id;
  title = body?.title ?? 'Otter Meeting';
  transcript = body?.transcript ?? '';
  summary = body?.summary ?? '';
  participants = (body?.speakers ?? []).map(s => s.email ?? s.name ?? '');
  startedAt = body?.started_at;
} else if (body?.granola_id) {
  source = 'granola';
  meetingId = body.granola_id;
  title = body?.title ?? 'Granola Meeting';
  transcript = body?.transcript ?? '';
  summary = body?.notes ?? body?.summary ?? '';
  participants = (body?.attendees ?? []).map(a => a.email ?? a);
  startedAt = body?.start_time;
} else {
  // Generic fallback shape
  meetingId = body?.id ?? body?.meeting_id ?? `unknown-${Date.now()}`;
  title = body?.title ?? body?.subject ?? 'Meeting';
  transcript = body?.transcript ?? body?.text ?? '';
  summary = body?.summary ?? '';
  participants = body?.participants ?? body?.attendees ?? body?.invitees ?? [];
  if (Array.isArray(participants) && participants[0] && typeof participants[0] === 'object') {
    participants = participants.map(p => p.email ?? p.name ?? String(p));
  }
  startedAt = body?.started_at ?? body?.start_time;
  source = body?.source ?? 'generic';
}

participants = (participants ?? [])
  .filter(Boolean)
  .map(p => String(p).trim().toLowerCase())
  .filter(p => p.length > 0);

if (participants.length === 0) {
  throw new Error('Cannot extract meeting key: no participants in payload.');
}

// Sorted participant set hash for stable cross-meeting recognition
const sortedParticipants = [...new Set(participants)].sort();
const crypto = require('crypto');
const participantKey = 'meeting-set:' + crypto
  .createHash('sha256')
  .update(sortedParticipants.join('|'))
  .digest('hex')
  .slice(0, 16);

return [{
  json: {
    meetingId,
    title,
    source,
    transcript: transcript.slice(0, 8000),  // cap to avoid LLM context blow
    summary,
    customerKey: participantKey,        // reuse customerKey naming for entity-lookup parity
    customerLabel: `Meeting set: ${sortedParticipants.join(', ').slice(0, 80)}`,
    participants: sortedParticipants,
    participantList: sortedParticipants.join(', '),
    participantCount: sortedParticipants.length,
    startedAt,
    receivedAt: new Date().toISOString(),
  },
}];

// Build a system + user prompt that asks the LLM to synthesize a cross-meeting
// summary, knowing what was discussed in prior meetings with the SAME participant set.
//
// The dossier comes from Memory: Meeting History (entity.open) for known sets,
// or Memory: Create Meeting Set for first-time. The LLM gets the new meeting's
// summary plus 5 most-recent prior meeting observations as context.

const customerKey = $('Extract Meeting Key').item.json.customerKey;
const meetingId = $('Extract Meeting Key').item.json.meetingId;
const title = $('Extract Meeting Key').item.json.title;
const summary = $('Extract Meeting Key').item.json.summary;
const transcript = $('Extract Meeting Key').item.json.transcript;
const participantList = $('Extract Meeting Key').item.json.participantList;

const dossierRaw = $input.first().json;
const dossier = dossierRaw?.data ?? dossierRaw;
const observations = dossier?.observations ?? [];
const priorMeetingCount = observations.length;
const priorContext = observations
  .slice(-5)
  .map(o => `- ${o?.created_at?.slice(0, 10) ?? '?'} ${(o?.content ?? '').slice(0, 300)}`)
  .join('\n');

const meetingInput = summary || transcript.slice(0, 4000);

const systemPrompt = `You are a meeting-context analyst. The same group of participants has met before. Your job is to summarize the LATEST meeting as a 4-sentence brief that highlights what is NEW versus what was already discussed in prior meetings, and what action items emerge that did not exist before.

Output format (markdown, NO preamble, NO em-dashes):

**${title}** (meeting ${meetingId.slice(0, 12)})

* Key takeaway from this meeting (1 sentence)
* New decisions or shifts since last meeting (1-2 sentences)
* Action items, who-owns-what (1-2 lines)
* Open questions for next time (1 line)

Participants: ${participantList}
Prior meetings on file with this exact set: ${priorMeetingCount}

Prior meeting observations (most-recent last):
${priorContext || '(no prior meetings on file with this participant set)'}

Latest meeting input:
${meetingInput}`;

return [{
  json: {
    systemPrompt,
    messageText: meetingInput,
    customerKey,
    customerLabel: $('Extract Meeting Key').item.json.customerLabel,
    meetingTitle: title,
    priorMeetingCount,
  },
}];

// LLM Fallback Reply for meeting summarization.
// Two arrival paths:
//   1. LLM error - input has $json.error
//   2. Router fallback - input has the original prompt object including
//      systemPrompt with prior meeting observations. We must NOT JSON.stringify.

const errorRaw = $input.first().json;
const provider = $('Set Provider').item.json.provider ?? 'unknown';

const isLlmError = !!(errorRaw?.error || errorRaw?.message);
let errorMessage;
if (isLlmError) {
  errorMessage = errorRaw?.error?.message
    ?? errorRaw?.error?.name
    ?? errorRaw?.message
    ?? 'Unknown LLM error';
} else {
  errorMessage = `Unknown provider value: ${provider}.`;
}

const customerKey = $('Extract Meeting Key').item.json.customerKey;
const meetingId = $('Extract Meeting Key').item.json.meetingId;
const title = $('Extract Meeting Key').item.json.title;
const messageText = $('Extract Meeting Key').item.json.summary || '(transcript unavailable)';

const fallbackText = `**${title}** (meeting ${String(meetingId).slice(0, 12)})\n\n* Summarizer is briefly down, please review the transcript manually.\n* No cross-meeting comparison available for this run.\n* Action: human review required.\n* Next: re-run when the LLM provider is back.`;

return [{
  json: {
    replyText: fallbackText,
    provider,
    isFallback: true,
    isRouterFallback: !isLlmError,
    errorMessage: String(errorMessage),
    customerKey,
    customerLabel: $('Extract Meeting Key').item.json.customerLabel,
    messageText,
  },
}];

// Normalize LLM output across providers into a single field `replyText`.
// OpenAI:    $json.choices[0].message.content
// Anthropic: $json.content[0].text

const raw = $input.first().json;
let replyText = '';

if (raw?.choices?.[0]?.message?.content) {
  replyText = raw.choices[0].message.content;
} else if (Array.isArray(raw?.content) && raw.content[0]?.text) {
  replyText = raw.content[0].text;
} else if (raw?.message?.content) {
  replyText = raw.message.content;
} else if (raw?.text) {
  replyText = raw.text;
} else if (raw?.reply) {
  replyText = raw.reply;
} else {
  replyText = '(LLM returned no text, check provider response shape)';
}

return [{
  json: {
    replyText: String(replyText).trim(),
    provider: $('Set Provider').item.json.provider,
    isFallback: false,
  },
}];
